def build_undirected_graph(vertices, edges):
    graph = {vertex: [] for vertex in vertices}
    for first, second in edges:
        graph[first].append(second)
        graph[second].append(first)
    return graph

graph = build_undirected_graph(range(4), [(0, 1), (1, 2), (1, 3)])

def build_matrix(vertex_count, edges, directed=False):
    matrix = [[0] * vertex_count for _ in range(vertex_count)]
    for source, target in edges:
        matrix[source][target] = 1
        if not directed:
            matrix[target][source] = 1
    return matrix

def dfs_recursive(graph, start):
    visited = set()
    order = []
    def visit(vertex):
        visited.add(vertex)
        order.append(vertex)
        for neighbor in graph[vertex]:
            if neighbor not in visited:
                visit(neighbor)
    visit(start)
    return order

def dfs_iterative(graph, start):
    visited = {start}
    stack = [start]
    order = []
    while stack:
        vertex = stack.pop()
        order.append(vertex)
        for neighbor in reversed(graph[vertex]):
            if neighbor not in visited:
                visited.add(neighbor)
                stack.append(neighbor)
    return order

from collections import deque

def bfs_order(graph, start):
    visited = {start}
    queue = deque([start])
    order = []
    while queue:
        vertex = queue.popleft()
        order.append(vertex)
        for neighbor in graph[vertex]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return order

def shortest_distances(graph, start):
    distance = {start: 0}
    queue = deque([start])
    while queue:
        vertex = queue.popleft()
        for neighbor in graph[vertex]:
            if neighbor not in distance:
                distance[neighbor] = distance[vertex] + 1
                queue.append(neighbor)
    return distance

def count_components(graph):
    visited = set()
    count = 0
    for start in graph:
        if start in visited:
            continue
        count += 1
        stack = [start]
        visited.add(start)
        while stack:
            vertex = stack.pop()
            for neighbor in graph[vertex]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)
    return count

def label_components(graph):
    component_of = {}
    component_id = 0
    for start in graph:
        if start in component_of:
            continue
        stack = [start]
        component_of[start] = component_id
        while stack:
            vertex = stack.pop()
            for neighbor in graph[vertex]:
                if neighbor not in component_of:
                    component_of[neighbor] = component_id
                    stack.append(neighbor)
        component_id += 1
    return component_of

def has_cycle_undirected(graph):
    visited = set()
    def dfs(vertex, parent):
        visited.add(vertex)
        for neighbor in graph[vertex]:
            if neighbor not in visited:
                if dfs(neighbor, vertex): return True
            elif neighbor != parent:
                return True
        return False
    return any(start not in visited and dfs(start, None) for start in graph)

def has_cycle_directed(graph):
    state = {vertex: 0 for vertex in graph}
    def dfs(vertex):
        state[vertex] = 1
        for neighbor in graph[vertex]:
            if state[neighbor] == 1: return True
            if state[neighbor] == 0 and dfs(neighbor): return True
        state[vertex] = 2
        return False
    return any(state[v] == 0 and dfs(v) for v in graph)

from collections import deque

def topological_sort(graph):
    indegree = {v: 0 for v in graph}
    for source in graph:
        for target in graph[source]: indegree[target] += 1
    queue = deque(v for v in graph if indegree[v] == 0)
    order = []
    while queue:
        vertex = queue.popleft(); order.append(vertex)
        for neighbor in graph[vertex]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0: queue.append(neighbor)
    return order if len(order) == len(graph) else []

def is_valid_topological_order(graph, order):
    if len(order) != len(graph): return False
    position = {vertex: index for index, vertex in enumerate(order)}
    return all(position[u] < position[v] for u in graph for v in graph[u])

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.component_size = [1] * size

    def find(self, item):
        if self.parent[item] != item:
            self.parent[item] = self.find(self.parent[item])
        return self.parent[item]

def union(self, first, second):
    root_first = self.find(first)
    root_second = self.find(second)
    if root_first == root_second:
        return False
    if self.component_size[root_first] < self.component_size[root_second]:
        root_first, root_second = root_second, root_first
    self.parent[root_second] = root_first
    self.component_size[root_first] += self.component_size[root_second]
    return True

def connected(self, first, second):
    return self.find(first) == self.find(second)

def first_redundant_edge(vertex_count, edges):
    union_find = UnionFind(vertex_count)
    for first, second in edges:
        if not union_find.union(first, second):
            return (first, second)
    return None
